  const {
    scenePosition = { x: 0, y: 0, z: 0 },
    sceneRotation = { x: 0, y: 0, z: 0 },
  } = config;

  const container = new THREE.Group();
  container.position.set(scenePosition.x, scenePosition.y, scenePosition.z);
  container.rotation.order = 'YXZ';
  container.rotation.set(sceneRotation.x, sceneRotation.y, sceneRotation.z);

