  const panelHeight = 1.9;
  const cornerRadius = 0.06;

  // === PANEL BACKGROUND ===
  const panelGeo = createRoundedRectGeometry(panelWidth, panelHeight, cornerRadius);
  disposables.push(panelGeo);

  const panelMat = new THREE.MeshStandardNodeMaterial({
    transparent: true,
    colorNode: TSL.mix(
      TSL.color(0x111116),
      TSL.color(0x1a1a22),
      TSL.positionLocal.y.add(panelHeight / 2).div(panelHeight)
    ),
