  }

  // === ATTRIBUTION TEXT ===
  let attributionTextMesh = null;
  if (ctx.fontAtlas && typeof ctx.fontAtlas.createTextMesh === 'function') {
    try {
      attributionTextMesh = ctx.fontAtlas.createTextMesh(
        "M. OKAFOR",
        {
          fontSize: 0.08,
          fontFamily: 'JetBrains Mono',
          fontWeight: 700,
          letterSpacing: 0.08,
          color: 0xe8ecf2,
        }
      );
      if (attributionTextMesh) {
        attributionTextMesh.position.set(-1.35, -0.5, 0.03);
        container.add(attributionTextMesh);
      }
    } catch (err) {
      console.warn('Failed to create attribution text:', err);
    }
  }

  // === CAPTION TEXT ===
  let captionTextMesh = null;
  if (ctx.fontAtlas && typeof ctx.fontAtlas.createTextMesh === 'function') {
    try {
      captionTextMesh = ctx.fontAtlas.createTextMesh(
        "COLLECTOR SINCE 2019",
