    color: 0xff2a38,
    emissive: 0xff2a38,
    emissiveIntensity: 1.4,
    metalness: 0,
    roughness: 1,
  });
  disposables.push(accentMat);

  const accentMesh = new THREE.Mesh(accentGeo, accentMat);
  accentMesh.position.set(-1.35, -0.35, 0.02);
  container.add(accentMesh);

  // === ANIMATIONS ===
  const mainTL = gsap.timeline({ paused: false });

  // Panel fade-up: opacity 0→1, y +0.2→0, 500ms, cubic-bezier
  const panelAnimState = { y: 0.2, opacity: 0 };
