/**
 * Create rounded rectangle plane geometry via Shape
 */
function createRoundedRectGeometry(width, height, radius) {
  const shape = new THREE.Shape();
  const x = -width / 2;
  const y = -height / 2;
  const w = width;
  const h = height;
  const r = Math.min(radius, w / 2, h / 2);

  shape.moveTo(x + r, y);
  shape.lineTo(x + w - r, y);
  shape.quadraticCurveTo(x + w, y, x + w, y + r);
  shape.lineTo(x + w, y + h - r);
  shape.quadraticCurveTo(x + w, y + h, x + w - r, y + h);
  shape.lineTo(x + r, y + h);
  shape.quadraticCurveTo(x, y + h, x, y + h - r);
  shape.lineTo(x, y + r);
  shape.quadraticCurveTo(x, y, x + r, y);

  return new THREE.ShapeGeometry(shape);
}

/**
 * Create extruded quotation mark via LatheGeometry
 */
function createQuoteMarkGeometry(height, depth) {
  const points = [];
  const steps = 24;

  for (let i = 0; i <= steps; i++) {
    const t = i / steps;
    const waveAmplitude = Math.sin(t * Math.PI * 2) * 0.04;
    const x = 0.14 + waveAmplitude;
    const y = -height / 2 + t * height;
    points.push(new THREE.Vector2(x, y));
  }

  const lathe = new THREE.LatheGeometry(points, 12, 0, Math.PI * 2);
  lathe.scale(1, 1, depth / 0.5);

  return lathe;
}
